.urc-select { border:1.5px solid #e2e8f0; border-radius:8px; padding:7px 11px; font-size:13px; background:#fff; color:#0f172a; cursor:pointer; min-width:200px; outline:none; transition:border-color .15s, box-shadow .15s; }
.urc-select:focus { border-color:#2563eb; box-shadow:0 0 0 3px rgba(37,99,235,.1); }
.urc-kpi-row { display:flex; gap:14px; align-items:stretch; margin-bottom:14px; flex-wrap:wrap; }
.urc-kpi { background:#fff; border:1px solid #e2e8f0; border-top:3px solid #dc2626; border-radius:12px; padding:16px 18px; min-width:220px; box-shadow:0 1px 3px rgba(0,0,0,.05); }
.urc-kpi-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; color:#94a3b8; margin-bottom:6px; }
.urc-kpi-val { font-size:30px; font-weight:800; color:#dc2626; line-height:1; }
.urc-kpi-trend { font-size:11px; font-weight:600; margin-top:8px; color:#94a3b8; }
.urc-trend-down { color:#059669; }
.urc-trend-up { color:#dc2626; }
.urc-trend-flat { color:#b45309; }
.urc-note { flex:1; min-width:240px; background:#fffbeb; border:1px solid #fde68a; border-radius:12px; padding:14px 16px; font-size:12px; color:#92400e; line-height:1.5; display:flex; align-items:center; }
.urc-table-wrap { overflow-x:auto; background:#fff; border:1px solid #e2e8f0; border-radius:12px; }
.urc-scroll { max-height:460px; overflow-y:auto; }
.urc-tbl { width:100%; border-collapse:collapse; font-size:13px; }
.urc-tbl th { position:sticky; top:0; background:#f8fafc; text-align:left; padding:10px 14px; font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; color:#94a3b8; border-bottom:2px solid #e2e8f0; white-space:nowrap; z-index:1; }
.urc-tbl td { padding:11px 14px; border-bottom:1px solid #f1f5f9; vertical-align:top; color:#334155; }
.urc-tbl tbody tr:hover td { background:#f8faff; }
.urc-cust { font-weight:600; color:#0f172a; }
.urc-muted { font-size:11px; color:#94a3b8; margin-top:2px; }
.urc-r { text-align:right; }
.urc-mono { font-variant-numeric:tabular-nums; }
.urc-out { font-weight:700; color:#dc2626; }
.urc-tfoot td { position:sticky; bottom:0; background:#f8fafc; border-top:2px solid #e2e8f0; font-weight:800; color:#0f172a; padding:11px 14px; }
.urc-empty { padding:28px 16px; text-align:center; color:#94a3b8; font-size:13px; }
.urc-loading { padding:28px; text-align:center; }
.urc-spin { display:inline-block; width:22px; height:22px; border:3px solid #e2e8f0; border-top-color:#dc2626; border-radius:50%; animation:urcSpin .7s linear infinite; }
@keyframes urcSpin { to { transform:rotate(360deg); } }

script:
(function(){
var root=root_element.querySelector('.dsync');if(!root)return;var isLab=root.classList.contains('dsync-lab');var method=isLab?'cannabis_management.api.daily_sync_dashboards.get_lab_daily_sync_dashboard':'cannabis_management.api.daily_sync_dashboards.get_sales_daily_sync_dashboard';function q(sel){return root.querySelector(sel)}function qa(sel){return Array.prototype.slice.call(root.querySelectorAll(sel))}function set(name,val){var el=q('[data-kpi="'+name+'"]');if(el)el.innerHTML=val}function money(v){v=parseFloat(v||0);if(Math.abs(v)>=1000000)return '$'+(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return '$'+(v/1000).toFixed(1)+'K';return '$'+v.toLocaleString(undefined,{maximumFractionDigits:0})}function num(v,d){return parseFloat(v||0).toLocaleString(undefined,{maximumFractionDigits:d==null?0:d})}function pct(v){return num(v,1)+'%'}function delta(v,suffix){v=parseFloat(v||0);var cls=v>=0?'style="color:#28a745;font-weight:800"':'style="color:#dc3545;font-weight:800"';return '<span '+cls+'>'+(v>=0?'up ':'down ')+num(Math.abs(v),1)+(suffix||'')+'</span> vs prior day'}function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function lineChart(el,rows,key,color){if(!el)return;rows=rows||[];key=key||'value';var vals=rows.map(function(r){return parseFloat(r[key]||0)});var max=Math.max.apply(null,vals.concat([0]));var min=Math.min.apply(null,vals.concat([0]));if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data for this period</div>';return}var w=620,h=170,p=18,span=Math.max(max-min,1);var pts=vals.map(function(v,i){var x=p+(i*(w-2*p)/Math.max(vals.length-1,1));var y=h-p-((v-min)/span*(h-2*p));return [x,y]});var d=pts.map(function(p,i){return(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)}).join(' ');var area=d+' L '+pts[pts.length-1][0]+' '+(h-p)+' L '+pts[0][0]+' '+(h-p)+' Z';el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none"><path class="dsync-fill" d="'+area+'"></path><path class="dsync-line" style="stroke:'+color+'" d="'+d+'"></path><line class="dsync-axis" x1="'+p+'" y1="'+(h-p)+'" x2="'+(w-p)+'" y2="'+(h-p)+'"></line></svg>'}
function barChart(el,rows,key,color){if(!el)return;rows=rows||[];key=key||'value';var vals=rows.map(function(r){return parseFloat(r[key]||0)});var max=Math.max.apply(null,vals.concat([0]));if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data for this period</div>';return}var w=620,h=170,p=18,bw=(w-2*p)/vals.length*.72;var bars=vals.map(function(v,i){var x=p+i*(w-2*p)/vals.length+bw*.2;var bh=(v/max)*(h-2*p);return '<rect class="dsync-bar" style="fill:'+color+'" x="'+x.toFixed(1)+'" y="'+(h-p-bh).toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+bh.toFixed(1)+'" rx="3"></rect>'}).join('');el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'+bars+'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p)+'" x2="'+(w-p)+'" y2="'+(h-p)+'"></line></svg>'}
function table(headers,rows){if(!rows||!rows.length)return '<div class="empty">No rows found.</div>';return '<table><thead><tr>'+headers.map(function(h){return'<th>'+esc(h.label)+'</th>'}).join('')+'</tr></thead><tbody>'+rows.map(function(r){return'<tr>'+headers.map(function(h){return'<td>'+h.f(r)+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table>'}
function renderSales(d){var s=d.summary||{},c=d.crm||{};set('cod_count',num(s.cod_unpaid_count));set('cod_count_delta',delta(s.cod_count_delta,''));set('cod_amount',money(s.cod_unpaid_amount));set('cod_amount_delta',delta(s.cod_amount_delta,' dollars'));set('prediction_accuracy',pct(s.prediction_accuracy));set('prediction_totals',money(s.prediction_received)+' received / '+money(s.prediction_expected)+' invoiced');set('target_pct',pct(s.sales_target_pct));set('target_totals',money(s.sales_month_actual)+' / '+money(s.sales_month_target));set('crm_leads',num(c.total_leads));set('crm_open',num(c.ongoing_deals));set('crm_won',num(c.won_deals));set('crm_conversion',pct(c.conversion_pct));lineChart(q('[data-chart="ar"]'),s.ar_trend,'value','#401090');lineChart(q('[data-chart="unreconciled"]'),s.unreconciled_trend,'value','#dc3545');q('[data-table="cash"]').innerHTML=table([{label:'Date',f:function(r){return esc(r.date)}},{label:'Type',f:function(r){return esc(r.type)}},{label:'Amount',f:function(r){return money(r.amount)}}],d.cash_bank_rows);q('[data-table="outstanding"]').innerHTML=table([{label:'Customer',f:function(r){return esc(r.customer)}},{label:'Amount',f:function(r){return money(r.amount)}},{label:'Days Overdue',f:function(r){return num(r.days_overdue)}}],d.outstanding_accounts)}
function renderLab(d){var p=d.production||{};set('lbs',num(p.lbs_ran,1));set('lbs_delta',delta(p.lbs_delta,' lbs'));set('hash_yield',pct(p.hash_yield_pct));set('hash_delta',delta(p.hash_yield_delta,'%'));set('rosin_yield',pct(p.rosin_yield_pct));set('rosin_delta',delta(p.rosin_yield_delta,'%'));var lb=q('[data-bar="lbs"]');if(lb)lb.style.width=Math.min((p.lbs_ran||0)/900*100,100)+'%';var hb=q('[data-bar="hash"]');if(hb)hb.style.width=Math.min((p.hash_yield_pct||0)/20*100,100)+'%';var rb=q('[data-bar="rosin"]');if(rb)rb.style.width=Math.min((p.rosin_yield_pct||0)/70*100,100)+'%';lineChart(q('[data-chart="hash"]'),d.trends,'hash_yield_pct','#C060E0');lineChart(q('[data-chart="rosin"]'),d.trends,'rosin_yield_pct','#401090');barChart(q('[data-chart="lbs"]'),d.trends,'lbs_ran','#401090');set('pending_invoices',num((d.pending_invoices||{}).count));lineChart(q('[data-chart="pending"]'),(d.pending_invoices||{}).trend,'value','#C060E0');var disc=d.discrepancies||{};set('disc_alert',(disc.open_count||0)+' open discrepancies'+(disc.doctype?' from '+esc(disc.doctype):' - reconciliation DocType not found'));q('[data-table="disc"]').innerHTML=table([{label:'Item',f:function(r){return esc(r.item)}},{label:'Status',f:function(r){return esc(r.status)}}],disc.rows);q('[data-table="eod"]').innerHTML=table([{label:'Run',f:function(r){return esc(r.run)}},{label:'Operator',f:function(r){return esc(r.operator)}},{label:'Input',f:function(r){return num(r.input_lbs,1)}},{label:'Hash %',f:function(r){return pct(r.hash_pct)}},{label:'Issue',f:function(r){return esc(r.issue||'-')}}],d.eod_rows);q('[data-table="shipments"]').innerHTML=table([{label:'DN #',f:function(r){return'<a href="/app/delivery-note/'+esc(r.name)+'" target="_blank">'+esc(r.name)+'</a>'}},{label:'Customer',f:function(r){return esc(r.customer)}},{label:'Items',f:function(r){return num(r.items)}},{label:'Total Qty',f:function(r){return num(r.qty,1)}},{label:'Value',f:function(r){return money(r.value)}}],(d.shipments||{}).rows);barChart(q('[data-chart="shipments"]'),(d.shipments||{}).trend,'value','#401090')}
function load(){qa('[data-kpi]').forEach(function(el){if(el.textContent==='...'||el.textContent==='Loading...')el.textContent='Loading...'});frappe.call({method:method,callback:function(r){var d=r.message||{};if(isLab)renderLab(d);else renderSales(d);set('last_refresh',new Date().toLocaleString())},error:function(){frappe.msgprint('Unable to load Daily Sync dashboard data.')}})}var btn=q('[data-action="refresh"]');if(btn)btn.addEventListener('click',load);load();setInterval(load,30*60*1000);
})();

